/* Фабрика записи FTS «Токен». */
fl_status kompilyator_flang_sozdat_token(fl_ctx *ctx, fl_value vid, fl_value znachenie, fl_value chislo, fl_value tekst, fl_value v_yolochkah, fl_value nizhniy, fl_value stroka, fl_value stolbec, fl_value *out, fl_error *error) {
  fl_value values[8];
  values[0] = vid; /* «вид» */
  values[1] = znachenie; /* «значение» */
  values[2] = chislo; /* «число» */
  values[3] = tekst; /* «текст» */
  values[4] = v_yolochkah; /* «в ёлочках» */
  values[5] = nizhniy; /* «нижний» */
  values[6] = stroka; /* «строка» */
  values[7] = stolbec; /* «столбец» */
  return fl_record_new(ctx, kompilyator_flang_names_1, values, 8, out, error);
}

/* Фабрика записи FTS «Диагностика». */
fl_status kompilyator_flang_sozdat_diagnostika(fl_ctx *ctx, fl_value kod, fl_value soobschenie, fl_value stroka, fl_value stolbec, fl_value *out, fl_error *error) {
  fl_value values[4];
  values[0] = kod; /* «код» */
  values[1] = soobschenie; /* «сообщение» */
  values[2] = stroka; /* «строка» */
  values[3] = stolbec; /* «столбец» */
  return fl_record_new(ctx, kompilyator_flang_names_2, values, 4, out, error);
}

