        FL_TRY(fl_sub(ctx, ostalos, fl_number(1.0), &fl_t599, error));
        const fl_value fl_t600 = sostoyanie;
        sostoyanie = fl_t600;
        simvoly = fl_t597;
        poziciya = fl_t598;
        ostalos = fl_t599;
        continue;
