/* Тело «Назвать сторожей спуска»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nazvat_storozhey_spuska_body(fl_ctx *ctx, fl_value troyki, fl_value zanyatye, fl_value gotovye, fl_value *result, fl_error *error) {
  for (;;) {
    FL_TRY(fl_tick(ctx, "Назвать сторожей спуска", error));
    if (fl_chain_empty(troyki)) {
      *result = gotovye;
      return FL_OK;
    } else if (fl_chain_cons(troyki)) {
      const fl_value golova = fl_chain_head(troyki); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(troyki); /* хвост «хвост» */
      fl_value fl_t8452 = fl_nothing();
      FL_TRY(kompilyator_flang_svobodnoe_imya_pri_ponizhenii(ctx, kompilyator_flang_text_943, zanyatye, zanyatye, fl_number(2.0), &fl_t8452, error));
      const fl_value imya = fl_t8452; /* пусть «имя» */
      fl_value fl_t8453 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, imya, zanyatye, &fl_t8453, error));
      fl_value fl_t8455[2];
      fl_t8455[0] = golova; /* «сообщения» */
      fl_t8455[1] = imya; /* «имя» */
      fl_value fl_t8454 = fl_nothing();
      FL_TRY(fl_record_new(ctx, kompilyator_flang_names_51, fl_t8455, 2, &fl_t8454, error));
      fl_value fl_t8456 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t8454, gotovye, &fl_t8456, error));
      troyki = hvost;
      zanyatye = fl_t8453;
      gotovye = fl_t8456;
      continue;
    } else {
      return fl_match_fail(ctx, troyki, error);
    }
  }
}

